"""Topic-linked 3D circuit builder and browser-side Arduino/DC learning simulator."""

import json

import streamlit.components.v1 as components

from ui.diagram_engine import _three_scripts


def render_circuit_lab(height=1030, focus_topic="Ohm's law and DC circuits"):
    """Render the interactive Industrial Electronics circuit workbench."""
    page = _TEMPLATE.replace("__THREE__", _three_scripts()).replace(
        "__TOPIC__", json.dumps(str(focus_topic), ensure_ascii=False)
    )
    components.html(page, height=height, scrolling=False)


